const clean = text => String(text).normalize('NFKC').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
export function findExamChapter(query,course='') {
  const phrase=clean(query);
  if(!phrase)return null;
  const namedCourse=phrase.match(/\b(?:biol|chem) (?:1406|1407|1411)\b/)?.[0]?.toUpperCase();
  const candidates=namedCourse||course?chapters.filter(chapter=>chapter.course===(namedCourse||course)):chapters;
  const number=phrase.match(/\b(?:chapters?|ch) ?(\d{1,2})\b/)?.[1];
  if(number){
    const numbered=candidates.filter(chapter=>chapter.number===Number(number));
    if(numbered.length===1)return numbered[0];
    if(numbered.length===0)return null;
    if(numbered.every(chapter=>chapter.course===numbered[0].course)){
      const first=numbered[0];
      return {...first,count:numbered.reduce((count,chapter)=>count+chapter.count,0)};
    }
  }
  const rank=candidates.flatMap(chapter=>{
    const names=[chapter.title,chapter.id,...(alias[chapter.id]??[])].map(clean);
    const score=Math.max(0,...names.filter(name=>name&&(' '+phrase+' ').includes(' '+name+' ')).map(name=>name.length));
    return score?[{chapter,score}]:[];
  }).sort((a,b)=>b.score-a.score);
  return rank[0]&&(!rank[1]||rank[0].score>rank[1].score)?rank[0].chapter:null;
}

export function examFollowups(chapterId) {
  const data=chapters.find(chapter=>chapter.id===chapterId);
  if(!data)return [];
  const g=split.get(data).topic.followup;
  return [
    ['What should I notice first about '+g.topic+'?',g.clue],
    ['How do I start solving this type of problem?',g.method],
    ['How can I check whether my answer makes sense?',g.check],
    ['What is an easy mistake to make here?',g.mistake],
    ['Why is '+g.topic+' useful?',g.reason+' '+g.transfer]
  ].map(([question,answer])=>({question,answer}));
}

function inputs(local) {
  return {a:1+local%101,b:1+Math.floor(local/101),local};
}

const format = (value,digits,fixed) => typeof value==='number'
  ? value.toLocaleString('en-US',{minimumFractionDigits:fixed?digits:0,maximumFractionDigits:digits??3,useGrouping:true})
  : value;

function optionsFor(row,index) {
  const values=[row.correct,...row.wrong];
  const fixed=/\bdecimal places\b/i.test(row.question);
  const display=[...new Set(values.map(value=>format(value,row.digits,fixed)+(row.unit??'')))].slice(0,4);
  if(display.length!==4)throw Error('Exam item needs four distinct answers at position '+index);
  const correct=display[0];
  // Mix both answer position and the ordering of distractors deterministically.
  const shift=(index*149+Math.floor(index/127))%4;
  const options=[...display.slice(4-shift),...display.slice(0,4-shift)];
  return {choices:options,correctIndex:options.indexOf(correct)};
}

function itemFollowups(row,choices,correctIndex) {
  const correct=choices[correctIndex];
  const other=choices.find((_,index)=>index!==correctIndex);
  const first=row.steps[0], last=row.steps.at(-1);
  return [
    ['What’s the best first step for this question?',first],
    ['How do I connect the givens to the answer?',row.steps.slice(1).join(' ')],
    ['Which answer choice fits the result?',correct+'. '+last],
    ['How can I check the choice “'+other+'”?',first+' '+last+' The worked solution gives '+correct+'.'],
    ['Which units or observations belong in my final explanation?',row.unit?
      'Report '+correct+' and keep the requested unit in the last line. '+last:
      'Name the conclusion and the evidence that supports it. '+first+' '+last]
  ].map(([question,answer])=>({question,answer}));
}

export function examQuestion(index,{includeFollowups=true,verify=false}={}) {
  if(!Number.isInteger(index)||index<0||index>=offset)return null;
  const data=chapters.find(chapter=>index>=chapter.start&&index<chapter.start+chapter.count);
  const {topic}=split.get(data);
  const row=topic.solve(inputs(index-data.start));
  if(verify&&(!row.check(row.correct)||row.steps.length<2||!row.question.trim())) {
    throw Error('Independent exam answer check failed for position '+index+' on '+data.id);
  }
  const result={id:'exam-'+index.toString().padStart(6,'0'),course:data.course,chapter:data.number,
    chapterId:data.id,title:data.title,question:row.question,...optionsFor(row,index),
    explanation:row.steps.join(' '),workedSteps:row.steps,source:topic.source,followupSet:data.id,
    calculation:typeof row.correct==='number'||!!row.unitWork?.length};
  if(includeFollowups)result.followups=[...examFollowups(data.id),...itemFollowups(row,result.choices,result.correctIndex)];
  if(row.unitWork?.length)result.unitWork=row.unitWork;
  return result;
}

const bank = () => import('./exam-bank.mjs?v=study-chat-1');
const clean = s => s.toLowerCase().replace(/[’‘]/g, "'").trim();
const coursePattern=/\b(?:biol?|chem)\s*14(?:06|07|11)\b/i;
const explicitCourse = text => text.match(coursePattern)?.[0].replace(/^bio(?=\s*\d)/i,'biol').replace(/\s*(\d{4})$/, ' $1').toUpperCase();
export const wantsExam = text => /\b(?:exam|test|multiple[ -]choice|mcq)\b/i.test(text)
  && !/\b(?:i have (?:an?|this)|here(?:'|’)s (?:an?|my)|my (?:teacher|professor|instructor) asked)\b/i.test(text)
  && (/\b(?:give|make|write|create|generate|quiz me|test me|i want|i need|show me)\b/i.test(text)
    || /^\s*(?:practice exam|mock (?:exam|test)|exam[ -]style|exam questions?|multiple[ -]choice|mcq)\b/i.test(text));
const numberTokens = text => [...text.replaceAll('−','-').matchAll(/(?<![\p{L}\d.])-?\d+(?:,\d{3})*(?:\.\d+)?(?!\d|\.\d)/gu)].map(m=>Number(m[0].replaceAll(',','')));

function promptTopic(text, activeTopic = '') {
  const contextual=/\b(?:on|about|for|from) (?:this|that|the same) topic\b/i.test(text);
  const after = text.match(/\b(?:on|about|covering|from|for|over)\s+(?:the topic of\s+)?(.+)/i)?.[1] ?? '';
  return (contextual ? activeTopic : (after || text.replace(/\b(?:can you|could you|would you|for me|give(?: me)?|make(?: me)?|write(?: me)?|create|generate|show me|quiz me|test me|i want|i need|please|an?|exam[ -]style|test[ -]style|multiple[ -]choice|practice|example|sample|mock|exam|test|questions?|mcq)\b/gi,' ')))
    .replace(coursePattern,' ')
    .replace(/\b(hess|boyle|charles|dalton|avogadro)[’']s\b/gi,'$1')
    .replace(/[?.!,]+$/g,'').replace(/\s+/g,' ').trim();
}

export function createExamChat({ chooseRandom = Math.random } = {}) {
  let active, reveal, chapter, lastIndex;
  const reset = () => { active = reveal = chapter = lastIndex = undefined; };
  async function start(text, selectedCourse, topic) {
    const {examManifest, examQuestion, findExamChapter} = await bank();
    const requested = explicitCourse(text) || selectedCourse;
    const requestedTopic = promptTopic(text, topic);
    const course = examManifest().courses.find(c => c.id === requested);
    const chapters = course?.chapters ?? examManifest().courses.flatMap(c => c.chapters);
    const chapterNumber=requestedTopic.match(/\b(?:chapter|ch)\.?\s*(\d{1,2})\b/i)?.[1];
    if (chapterNumber && !course) {
      reset();
      return {kind:'prompt',text:'Which course do you mean by chapter '+chapterNumber+'?',actions:examCourseActions(requestedTopic)};
    }
    const selected = requestedTopic ? findExamChapter(requestedTopic, requested) : null;
    const topicWithoutChapter=chapterNumber&&requestedTopic.replace(/\b(?:chapter|ch)\.?\s*\d{1,2}\b/i,'').replace(/^(?:\W|on\b|about\b|for\b)+/i,'').trim();
    const topicMatch=topicWithoutChapter&&findExamChapter(topicWithoutChapter,requested);
    if (selected && topicMatch && topicMatch.number!==selected.number){
      reset();
      return {kind:'prompt',text:'That chapter number and topic point to different parts of this practice bank. Ask by topic or by chapter to choose one.'};
    }
    if (requestedTopic && !selected) {
      reset();
      return {kind:'prompt', text:'I couldn’t match that topic to an exam-style question yet. Try a chapter name such as cell division, membrane transport, evolution, gas laws, or thermochemistry.'};
    }
    if (!selected && !course) {
      reset();
      return {kind:'prompt', text:'Which course should the practice question come from?', actions:examCourseActions()};
    }
    chapter = selected ?? chapters[Math.floor(chooseRandom() * chapters.length)];
    return another(examQuestion);
  }
  function another(examQuestion) {
    let offset = Math.floor(chooseRandom()*chapter.count);
    if (chapter.start + offset === lastIndex && chapter.count > 1) offset = (offset+1)%chapter.count;
    lastIndex = chapter.start + offset;
    active = examQuestion(lastIndex);
    reveal = false;
    return {kind:'question', text:'Try this exam-style question. Choose an answer or ask for a hint.', item:active};
  }
  async function respond(text, selectedCourse, topic, itemId) {
    if (itemId && itemId !== active?.id) {
      const m = /^exam-(\d{6})$/.exec(itemId);
      if (!m) return null;
      const {examManifest, examQuestion} = await bank();
      const loaded = examQuestion(Number(m[1]));
      const owner = examManifest().courses.find(c => c.id === loaded?.course)?.chapters.find(c => c.id === loaded.chapterId);
      if (!loaded || !owner) return null;
      active = loaded;
      chapter = owner;
      lastIndex = Number(m[1]);
      reveal = true;
    }
    if (wantsExam(text)) return start(text, selectedCourse, topic);
    if (!active) return null;
    const q=clean(text).replace(/[?.!]$/, '');
    if (/^(?:another|next|one more)(?: (?:exam|practice|similar))?(?: (?:one|question|problem))?$/.test(q)){
      const {examQuestion} = await bank();
      return another(examQuestion);
    }
    if (/^(?:please )?(?:(?:give me|show me|i need|can i get) (?:a |one )?)?(?:hint|hints|where do i start)$/.test(q)) {
      return {kind:'hint', text:active.hint || 'Read the last sentence first. Identify the quantity or result it asks you for, then find the details that would let you check each choice.', item:active};
    }
    const pick = q.match(/^(?:(?:i (?:pick|choose|think it'?s)|option|answer)\s+)?([abcd])(?:[).:])?$/);
    const matched = active.choices.findIndex(choice => clean(choice) === q);
    if (pick || matched >= 0 || /^(?:(?:can|could) you )?(?:show|reveal)(?: me)? (?:(?:the|your) )?(?:answer|solution|work|explanation)\b|^explain (?:the )?answer$/.test(q)){
      const chosen = pick ? pick[1].charCodeAt()-97 : matched;
      const feedback = chosen < 0 ? 'Here’s the worked answer.' : chosen === active.correctIndex
        ? 'That’s right. Here’s why it works.' : 'Not quite. Here’s how to find the correct answer.';
      reveal = true;
      return {kind:'answer', text:feedback, item:active};
    }
    if (reveal) {
      const followup = active.followups.find(f => clean(f.question).replace(/[?.!]$/,'') === q);
      if (followup) return {kind:'followup', text:followup.answer, item:active};
      const worked=active.workedSteps.map(step=>typeof step==='string'?step:step.explanation);
      if (/^(?:(?:can|could) you )?(?:break (?:this|that|it|the answer) down|walk me through(?: (?:that|it|this))?|explain that again)$/.test(q)) {
        return {kind:'followup', text:worked.join(' '), item:active};
      }
      if (/^(?:how (?:did|do) you (?:get|find|calculate)|where (?:did|does) .+ come from)\b/.test(q)) {
        const [number]=numberTokens(q);
        const line=number!==undefined&&worked.find(step=>numberTokens(step).includes(number));
        const finalChoice=active.choices[active.correctIndex];
        const resultLine=number!==undefined&&numberTokens(finalChoice).includes(number)
          ? worked.slice(-2).join(' ')+' That gives '+finalChoice+'.' : '';
        const text=resultLine||line||(number!==undefined?'I don’t see that number in the worked answer. Which line are you looking at?':worked.join(' '));
        return {kind:'followup', text, item:active};
      }
      if (/^(?:which|what) units (?:cancel|canceled|cancelled|are left)\b/.test(q) && (active.unitWork?.length||active.unitChain?.length)){
        return {kind:'followup', text:'Look for the same unit spelled out above and below the fraction bar. Those units cancel. Use the units left over to check the answer.', item:active, showUnits:true};
      }
      if (/^(?:what (?:formula|equation) (?:did you use|should i use)|why (?:did you (?:use|pick|choose) (?:that|this)(?: (?:formula|equation|method))?|that (?:formula|equation|method)))$/.test(q)){
        const chosen=worked.find(step=>/[=×÷]/.test(step))??worked[0];
        return {kind:'followup', text:chosen, item:active};
      }
      if (/^why (?:did|do|would) (?:i|you|we) (?:divide|multiply)\b/.test(q)){
        const operation=q.includes('divide') ? /\bdivid|÷/i : /\bmultip|×/i;
        const [number]=numberTokens(q);
        const line=worked.find(step=>operation.test(step)&&(number===undefined||numberTokens(step).includes(number)));
        return {kind:'followup',text:line||'Which step are you looking at? Quote the line or give me the two values you’re combining.',item:active};
      }
    }
    reset();
    return null;
  }
  return {respond, reset};
}

function examCourseActions(topic='') {
  return ['BIOL 1406','BIOL 1407','CHEM 1411'].map(course=>[course,
    'Give me an exam-style practice question for '+course+(topic?' on '+topic:'')]);
}

export function renderExamChat(reply, result, ask, typeset, dimensionalAnalysis) {
  const d=reply.ownerDocument;
  const block=d.createElement('section'); block.className='exam-chat-card'; reply.append(block);
  const el=(tag,text,parent=block)=>{const node=d.createElement(tag);if(text)node.textContent=text;parent.append(node);return node;};
  const button=(label,prompt,parent=block)=>{const b=el('button',label,parent);b.type='button';b.addEventListener('click',()=>ask(prompt,result.item?.id));return b;};
  if(result.actions?.length){const controls=el('div','');controls.className='learning-followups';for(const [label,prompt] of result.actions)button(label,prompt,controls);}
  const item=result.item;
  if(!item)return;
  if(result.kind==='question'){
    el('h4',[item.course, item.chapterTitle ?? item.title].filter(Boolean).join(' · '));
    const stem=el('p',''); typeset(stem,item.question);
    const options=el('ol',''); options.className='exam-chat-options'; options.setAttribute('aria-label','Answer options');
    for(const [i,choice] of item.choices.entries()){
      const row=el('li','',options);const letter=String.fromCharCode(65+i);
      const choiceButton=button('', 'Option '+letter,row);typeset(choiceButton,letter+'. '+choice);
    }
    const controls=el('div','');controls.className='learning-followups';
    button('Give me a hint','Give me a hint',controls);
    button('Reveal answer','Reveal the answer',controls);
  }
  if(result.kind==='answer'){
    const correct=el('p','');const best=el('strong','',correct);
    typeset(best,'Correct answer · '+String.fromCharCode(65+item.correctIndex)+'. '+item.choices[item.correctIndex]);
    if(item.explanation && item.explanation !== item.workedSteps?.join(' ')) {
      const why=el('p','');typeset(why,item.explanation);
    }
    showUnitWork();
    if(item.workedSteps?.length){
      const steps=el('ol','');
      for(const line of item.workedSteps){const step=el('li','',steps);typeset(step,typeof line==='string'?line:line.explanation);}
    }
    if(item.followups?.length){
      const details=el('details','');el('summary','Explore 10 follow-up questions',details);
      const controls=el('div','',details);controls.className='learning-followups';
      for(const f of item.followups)button(f.question,f.question,controls);
    }
    const controls=el('div','');controls.className='learning-followups';
    button('Another question','Another question',controls);
  }
  if(result.showUnits)showUnitWork();
  function showUnitWork(){
    for(const work of item.unitWork??(item.unitChain?.length?[{label:'Set up the unit conversion',chain:item.unitChain}]:[])){
      el('h4',work.label);
      dimensionalAnalysis?.(block,work.chain);
      if(work.result)typeset(el('p',''),'= '+work.result);
    }
  }
  if(['answer','followup'].includes(result.kind)&&item.source?.length){
    const [title,url]=item.source;
    if(/^https:\/\//.test(url)){
      const links=el('div','');links.className='source-links';
      const a=el('a',title,links);a.href=url;a.target='_blank';a.rel='noopener noreferrer';
    }
  }
}

