const source = (book, page, title) => ['OpenStax · ' + title, 'https://openstax.org/books/' + book + '/pages/' + page];
const chemistry = (page, title) => source('chemistry-2e', page, title);
const biology = (page, title) => source('biology-2e', page, title);
const conversion = chemistry('1-6-mathematical-treatment-of-measurement-results', 'Unit conversions');
const moleSource = chemistry('3-1-formula-mass-and-the-mole-concept', 'Formula mass and moles');
const concentrationSource = chemistry('3-3-molarity', 'Molarity and dilution');
const gasSource = chemistry('9-2-relating-pressure-volume-amount-and-temperature-the-ideal-gas-law', 'Ideal gas law');
const heatSource = chemistry('5-2-calorimetry', 'Calorimetry');
const populationSource = biology('19-1-population-evolution', 'Hardy–Weinberg equilibrium');
const indexSource = ['Lycoming College · Mitotic index', 'https://newman.lycoming.edu/Bio110IntroBio/Lab06-Mitosis-Meiosis-Mendel.pdf'];

const numberPattern = '[+−-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[Ee][+−-]?\\d+)?';
const unit = (pattern, kind, label, scale = 1, offset = 0) => ({pattern, kind, label, scale, offset});
const unitPatterns = [
  unit('(?:kJ|J)\\s*(?:/| per )\\s*\\(?(?:kg|g)\\s*(?:·|⋅|\\*|/|[-–])?\\s*(?:°\\s*C|K)\\)?', 'specific-heat', ''),
  unit('g\\s*(?:/| per )\\s*mol', 'molar-mass', 'g/mol'),
  unit('(?:mol\\s*(?:/| per )\\s*(?:L|lit(?:er|re)s?)|M)', 'concentration', 'mol/L'),
  unit('kg|kilograms?', 'mass', 'kg', 1000), unit('mg|milligrams?', 'mass', 'mg', 0.001),
  unit('g|grams?', 'mass', 'g'),
  unit('mmol|millimoles?', 'amount', 'mmol', 0.001), unit('mol|moles?', 'amount', 'mol'),
  unit('mL|millilit(?:er|re)s?|cm[³3]', 'volume', 'mL', 0.001),
  unit('L|lit(?:er|re)s?', 'volume', 'L'), unit('m[³3]', 'volume', 'm³', 1000),
  unit('kPa', 'pressure', 'kPa'), unit('Pa', 'pressure', 'Pa', 0.001),
  unit('atm|atmospheres?', 'pressure', 'atm', 101.325), unit('bar', 'pressure', 'bar', 100),
  unit('torr|mm\\s*Hg', 'pressure', 'torr', 101.325 / 760),
  unit('°\\s*C|degrees? Celsius', 'temperature', '°C', 1, 273.15),
  unit('K|kelvins?', 'temperature', 'K'), unit('%|percent', 'percent', '%')
].map(item => ({...item, matcher: new RegExp('^(?:' + item.pattern + ')$', 'i')}));

const measurePattern = new RegExp(
  '(?<![A-Za-z0-9.])(' + numberPattern + ')\\s*(' +
  unitPatterns.map(item => item.pattern).join('|') + ')(?![A-Za-z0-9²³/])', 'gi'
);
const baseUnit = {mass: 'g', amount: 'mol', volume: 'L', pressure: 'kPa', temperature: 'K', concentration: 'mol/L'};
const numeric = value => Number(value.replace('−', '-'));
const display = value => {
  if (!Number.isFinite(value)) return '?';
  return String(Number(value.toPrecision(9))).replace(/e-/, ' × 10^−').replace(/e\+?/, ' × 10^');
};
const expand = (value, label) => display(value) + (label ? ' ' + label : '');

function parseMeasures(input) {
  return [...input.matchAll(measurePattern)].flatMap(match => {
    const [quote, raw, spelling] = match;
    const type = unitPatterns.find(item => item.matcher.test(spelling));
    // Preserve the distinction between molarity M and meters m.
    if (!type || spelling === 'm' || spelling === 'k') return [];
    const value = numeric(raw);
    if (!Number.isFinite(value)) return [];
    let {scale, label} = type;
    if (type.kind === 'specific-heat') {
      const inKiloJoules = /^kJ/i.test(spelling);
      const perKiloGram = /kg/i.test(spelling);
      label = (inKiloJoules ? 'kJ' : 'J') + '/(' + (perKiloGram ? 'kg' : 'g') + '·' + (/°/u.test(spelling) ? '°C' : 'K') + ')';
      scale = (inKiloJoules ? 1000 : 1) / (perKiloGram ? 1000 : 1);
    }
    return [{quote, raw, value, normalized: value * scale + type.offset, label, scale, offset:type.offset, kind: type.kind,
      index: match.index, end: match.index + quote.length}];
  });
}

const given = (item, meaning) => ({quote:item.quote, role:'Given', meaning});
const target = (quote, meaning) => ({quote, role:'Target', meaning});
const condition = (quote, meaning) => ({quote, role:'Condition', meaning});
const find = (input, pattern) => input.match(pattern)?.[0] ?? '';
const finite = value => Number.isFinite(value) && Math.abs(value) < 1e100;
const positive = item => item && finite(item.normalized) && item.normalized > 0;
const nonnegative = item => item && finite(item.normalized) && item.normalized >= 0;
const one = values => values.length === 1 ? values[0] : null;
const line = (value, ...units) => ({value:String(value), units:units.map(text => text.endsWith('!') ?
  {text:text.slice(0,-1),cancel:true}:{text,cancel:false})});
const factor = (top, bottom) => bottom ? {top,bottom} : {top};
const convertedNumber = item => {
  if(item.normalized===item.value)return item.raw;
  const mantissa=item.raw.replace(/^[+−-]/,'').split(/[Ee]/)[0];
  const digits=mantissa.includes('.')?mantissa.replace('.','').replace(/^0+/,'').length:0;
  if(item.offset||!digits||!item.normalized||digits>9)return display(item.normalized);
  return item.normalized.toPrecision(digits).replace(/e-/,' × 10^−').replace(/e\+?/,' × 10^');
};
const convertedValue = (item, label) => convertedNumber(item)+' '+label;
const stepLine = (item, base = baseUnit[item.kind]) => item.normalized === item.value && item.label === base
  ? '' : item.quote + ' = ' + convertedValue(item, base) + '.';

function answerNumber(input, value, unitName) {
  if (!finite(value)) return null;
  const places = Number(input.match(/\b(?:to|using|with)\s+([1-8])\s+decimal places?\b/i)?.[1] ?? 0);
  const figures = Number(input.match(/\b(?:to|using|with)\s+([1-8])\s+(?:significant figures?|sig(?:nificant)?\s*figs?)\b/i)?.[1] ?? 0);
  const number = places ? value.toFixed(places) : figures ? value.toPrecision(figures) : display(value);
  return number + (unitName === '%' ? '%' : unitName ? ' ' + unitName : '');
}

function guide(topic, title, text, formula, links, clues = []) {
  const parts = clues.filter(part => part.quote);
  return (steps, options = {}) => ({
    topic,intent:'approach',title,text,steps:steps.filter(Boolean),formula,parts,links,
    ...options
  });
}

function massMoles(input, units) {
  const toMoles = find(input,/\b(?:(?:how many|what(?: is|['’]s)(?: the)?|calculate(?: the)?|find(?: the)?|determine(?: the)?)\s+(?:number of\s+)?mol(?:es)?|(?:g|grams?|mass)\s*(?:to|into|→)\s*mol(?:es)?)\b/i);
  const toMass = find(input,/\b(?:(?:how many|what(?: is|['’]s)(?: the)?|calculate(?: the)?|find(?: the)?|determine(?: the)?)\s+(?:g|grams?|mass)|(?:mol(?:es)?)\s*(?:to|into|→)\s*(?:grams?|g)|how much (?:does|do) .+? weigh)\b/i);
  const masses = units('mass'), amounts = units('amount'), molarMasses = units('molar-mass');
  if (!toMoles && !toMass) return null;
  if (!(masses.length || amounts.length || molarMasses.length)) return null;
  const toAmount = !!toMoles && !toMass;
  const mass = one(masses), amount = one(amounts), mm = one(molarMasses);
  const suspectReaction = /\b(?:limiting|in excess|balanced reaction|according to (?:the|this) reaction|of product|reactant-to-product|stoichiometry)\b/i.test(input);
  const original = toAmount ? mass : amount;
  const report = guide('moles','Grams and moles',
    toAmount ? 'Start with the sample mass. Molar mass tells you how many grams are in one mole of that substance.'
      : 'Start with the amount in moles. Use the molar mass to find how many grams that amount weighs.',
    toAmount ? 'n = m / Mₘ' : 'm = n × Mₘ',[moleSource, conversion],
    [...masses.map(x=>given(x,'Mass in the problem')), ...amounts.map(x=>given(x,'Amount in the problem')),
      ...molarMasses.map(x=>given(x,'Mass per mole')),target(toMoles || toMass,toAmount?'Find the amount in moles':'Find the mass in grams')]);
  if ((toMoles && toMass) || suspectReaction || (toAmount && amounts.length) || (!toAmount && masses.length)) {
    return report(['For one substance, molar mass relates its grams and moles. If the question changes substances in a reaction, first use the mole ratio from the balanced equation.'],
      {question:'Which single substance and quantity are you solving for?'});
  }
  if (!positive(mm) || !nonnegative(original)) {
    return report(['Write one starting amount, including its unit.','Use the molar mass of that same substance in g/mol.'],
      {question:!positive(mm)?'What molar mass in g/mol does the problem supply for the substance?':'Which starting quantity belongs to this substance?'});
  }
  const inputSpecies = input.slice(original.end).match(/^\s+of\s+([A-Za-z][A-Za-z0-9₀-₉-]*)/i)?.[1];
  const suppliedSpecies = input.match(/\bmolar mass of\s+([A-Za-z][A-Za-z0-9₀-₉-]*)\b/i)?.[1];
  if(inputSpecies && suppliedSpecies && inputSpecies.toLowerCase()!==suppliedSpecies.toLowerCase()) {
    return report(['Check the substance labels. The given amount and the molar mass need to describe the same substance.'],
      {question:'Is the supplied molar mass for the substance you are converting?'});
  }
  const unitName = toAmount ? 'mol' : 'g';
  const value = toAmount ? mass.normalized / mm.value : amount.normalized * mm.value;
  const answer = answerNumber(input,value,unitName);
  if(!answer)return report(['Check the given amounts and units before substituting.'],{question:'Can you confirm the numbers in the problem?'});
  return report([
    stepLine(original),
    toAmount ? 'Put grams on the bottom of the conversion factor so the grams cancel.' :
      'Put moles on the bottom of the conversion factor so the moles cancel.',
    toAmount ? expand(mass.normalized,'g') + ' ÷ ' + expand(mm.value,'g/mol') + ' = ' + answer + '.' :
      expand(amount.normalized,'mol') + ' × ' + expand(mm.value,'g/mol') + ' = ' + answer + '.'
  ],{answer,unitChain:toAmount?
    [factor(line(display(mass.normalized),'g!')),factor(line(1,'mol'),line(mm.raw,'g!'))]:
    [factor(line(display(amount.normalized),'mol!')),factor(line(mm.raw,'g'),line(1,'mol!'))]});
}

function concentration(input, units) {
  const dilution = /\b(?:dilut\w*|stock solution|stock concentration|M[₁1]V[₁1])\b/i.test(input);
  const targetM = find(input,/\b(?:(?:what is|find|calculate|determine)\s+(?:the\s+)?(?:final |resulting |new )?(?:molarity|concentration)|what (?:molarity|concentration)|(?:find|calculate|determine)\s+M[₂2])\b/i);
  const targetN = find(input,/\b(?:(?:how many|calculate(?: the)?|find(?: the)?|determine(?: the)?)\s+(?:number of\s+)?moles?)\b/i);
  const targetV = find(input,/\b(?:(?:what|find|calculate|determine)\s+(?:is\s+)?(?:the\s+)?(?:initial |final |stock |total )?volume|how (?:much|many)\b[^?.!]{0,65}\bstock)\b/i);
  const volumes = units('volume'), concentrations = units('concentration'), amounts = units('amount');
  const masses = units('mass'), molarMasses = units('molar-mass');
  if (!(volumes.length || concentrations.length || amounts.length) ||
      (!dilution && !targetM && !(targetV && concentrations.length) && !(targetN && concentrations.length))) return null;
  const report = guide(dilution?'dilution':'molarity',dilution?'Dilution':'Molarity',
    dilution?'Ask what stays the same. Adding solvent changes the volume and concentration, while the amount of the original solute stays fixed.':
      'Molarity connects moles of solute to liters of the full solution. Identify the requested quantity before substituting.',
    dilution?'M₁V₁ = M₂V₂':targetN?'n = M × V':targetV?'V = n / M':'M = n / V',
    [concentrationSource, conversion],
    [...concentrations.map(x=>given(x,'The concentration measures moles of solute per liter of solution.')),
      ...volumes.map(x=>given(x,dilution?'Check whether the wording makes this the stock volume or the final total volume.':
        'Molarity uses total solution volume in liters. This belongs in the denominator when you calculate concentration.')),
      ...amounts.map(x=>given(x,'This counts the solute. Moles of solute go in the numerator when you calculate concentration.')),
      ...masses.map(x=>given(x,'Convert the mass of the solute to moles before using it in a concentration equation.')),
      ...molarMasses.map(x=>given(x,'This connects grams of this solute to one mole of it.')),
      target(targetM||targetN||targetV,targetM?'Report moles of solute per liter of solution (M).':targetN?'Report moles of solute.':'Report the volume of the solution.'),
      condition(find(input,/\b(?:dilut\w*|(?:adding|add) (?:water|solvent))\b/i),'Solvent is added to a stock solution')]);
  if (dilution) {
    const conflicting = /\b(?:another solute|mixed with (?:a|an|the|another) (?:stock|solution)|react\w*|evaporat\w*)\b/i.test(input);
    if (conflicting) return report(['M₁V₁ = M₂V₂ applies to solvent-only dilution. Track each source of solute separately if solutions are mixed or react.'],
      {question:'Is this a dilution with solvent only, or are you mixing solutions?'});
    const addedSolvent = volumes.some(item =>
      /^\s+(?:of\s+)?(?:water|solvent)\b/i.test(input.slice(item.end)) &&
      /\b(?:with|add(?:s|ed|ing)?)\s*$/i.test(input.slice(Math.max(0,item.index-22),item.index))
    );
    if (addedSolvent) return report(['Use the final total solution volume for V₂. The amount of solvent added describes a different quantity.'],
      {question:'What is the final total volume after you add the solvent?'});
    const mc = one(concentrations);
    const vc = one(volumes);
    const toFinalConc = !!targetM && concentrations.length===1 && volumes.length===2 &&
      !/\b(?:initial|stock) (?:molarity|concentration)\b/i.test(targetM);
    const toStockVolume = !!targetV && /\b(?:stock|initial)\b/i.test(targetV) &&
      concentrations.length===2 && volumes.length===1;
    const toFinalVolume = !!targetV && /\b(?:final|total)\b/i.test(targetV) &&
      concentrations.length===2 && volumes.length===1;
    if (toFinalConc && positive(mc) && volumes.every(positive)) {
      const first = volumes[0], last = volumes[1];
      const explicitIncrease = /\b(?:dilut\w*|bring|brought|make|fill)\b[\s\S]{0,120}\b(?:to|final|total)\b/i.test(input)
        || /\b(?:final volume|volume after dilution)\b/i.test(input);
      if (!explicitIncrease || last.normalized < first.normalized) return report(['Label the stock aliquot V₁ and the larger final total volume V₂ before dividing.'],
        {question:'Which volume is the starting stock aliquot and which is the final volume?'});
      const value = mc.normalized * first.normalized / last.normalized;
      const answer=answerNumber(input,value,'M');
      return report(['Rearrange for the final concentration, M₂ = M₁V₁ / V₂.',
        stepLine(first),stepLine(last),
        expand(mc.normalized,'mol/L') + ' × (' + expand(first.normalized,'L') + ' / ' + expand(last.normalized,'L') + ') = ' + answer + '.',
        'The volume grew, so the concentration should be lower than the stock concentration.'],
      {answer,unitChain:[factor(line(mc.raw,'mol/L')),factor(line(display(first.normalized),'L!'),line(display(last.normalized),'L!'))]});
    }
    if ((toStockVolume || toFinalVolume) && positive(vc) && concentrations.every(positive)) {
      const stock = concentrations.find(item => /\bstock\b/i.test(input.slice(Math.max(0,item.index-22),item.end+22)));
      const final = stock && concentrations.find(item=>item!==stock);
      if (stock && final && stock.normalized>final.normalized) {
        const numerator=toStockVolume ? final : stock,denominator=toStockVolume ? stock : final;
        const value=vc.normalized*numerator.normalized/denominator.normalized;
        const answer=answerNumber(input,value,'L');
        return report([toStockVolume?'Rearrange for the stock volume, V₁ = M₂V₂ / M₁.':'Rearrange for the final volume, V₂ = M₁V₁ / M₂.',
          stepLine(vc),expand(vc.normalized,'L')+' × ('+expand(numerator.normalized,'mol/L')+' / '+expand(denominator.normalized,'mol/L')+') = '+answer+'.'],
        {answer,unitChain:[factor(line(display(vc.normalized),'L')),factor(line(numerator.raw,'mol/L!'),line(denominator.raw,'mol/L!'))]});
      }
    }
    return report(['Label the stock concentration and volume M₁ and V₁. Label the final concentration and total volume M₂ and V₂.','Solve for the missing value after identifying the three given quantities.'],
      {question:'Which quantities belong to the stock and which describe the final solution?'});
  }
  const amount = one(amounts), vol = one(volumes), molarity = one(concentrations);
  const solventOnly = /\b(?:mL|L|millilit(?:er|re)s?|lit(?:er|re)s?)\s+(?:of\s+)?(?:water|solvent)\b/i.test(input) &&
    !/\b(?:final|total) (?:solution )?volume\b|\b(?:solution (?:has|is|of|volume))\b/i.test(input);
  if (solventOnly) return report(['Use the final volume of the solution. The volume of water used can be different from the final solution volume.'],
    {question:'What is the final volume after dissolving the solute?'});
  const mm = one(molarMasses), mass = one(masses);
  let n = amount?.normalized;
  const fromMass = !amount && !amounts.length && nonnegative(mass) && positive(mm);
  if (fromMass) n=mass.normalized/mm.normalized;
  let value, unitName, chain, arithmetic;
  if (targetM && !targetN && !targetV && positive(vol) && finite(n) && n>=0 && !concentrations.length) {
    value=n/vol.normalized;unitName='M';
    chain=[factor(line(amount?convertedNumber(amount):display(n),'mol'),line(convertedNumber(vol),'L'))];
    arithmetic=(amount?convertedValue(amount,'mol'):expand(n,'mol'))+' ÷ '+convertedValue(vol,'L');
  } else if(targetN && !targetM && !targetV && positive(vol) && nonnegative(molarity) && !amounts.length) {
    value=molarity.normalized*vol.normalized;unitName='mol';
    chain=[factor(line(molarity.raw,'mol'),line(1,'L!')),factor(line(display(vol.normalized),'L!'))];
    arithmetic=expand(molarity.normalized,'mol/L')+' × '+expand(vol.normalized,'L');
  } else if(targetV && !targetN && !targetM && positive(molarity) && finite(n) && n>=0 && !volumes.length) {
    value=n/molarity.normalized;unitName='L';
    chain=[factor(line(display(n),'mol!')),factor(line(1,'L'),line(molarity.raw,'mol!'))];
    arithmetic=expand(n,'mol')+' ÷ '+expand(molarity.normalized,'mol/L');
  }
  const answer=answerNumber(input,value,unitName);
  if (!answer) return report(['Label moles of solute, concentration, and liters of the final solution. If you start from grams, supply that solute’s molar mass to convert to moles.'],
    {question:'Can you identify the two given amounts and which value you need to find?'});
  const unitWork=fromMass?[{label:'Convert grams of solute to moles',
    chain:[factor(line(display(mass.normalized),'g!')),factor(line(1,'mol'),line(mm.raw,'g!'))],
    result:expand(n,'mol')}]:[];
  return report([fromMass?stepLine(mass):'',fromMass?expand(mass.normalized,'g')+' ÷ '+expand(mm.normalized,'g/mol')+' = '+expand(n,'mol')+'.':'',
    vol?stepLine(vol):'',arithmetic+' = '+answer+'.'],{answer,unitChain:chain,unitWork});
}

function calorimetry(input, units) {
  const desired = find(input,/\b(?:how much heat|(?:what is|find|calculate|determine) (?:the )?(?:amount of )?heat(?: energy)?|find q|calculate q)\b/i);
  const masses = units('mass'), temperatures = units('temperature'), specificHeats = units('specific-heat');
  const heatClue = find(input,/\b(?:calorimetry|specific heat|absorbs? heat|releases? heat|heat (?:absorbed|released|transfer)|warm(?:s|ed)?|cool(?:s|ed)?)\b/i);
  if(!desired || !(masses.length+temperatures.length+specificHeats.length) || (!heatClue && !specificHeats.length))return null;
  const mass=one(masses), c=one(specificHeats);
  const noPhase=find(input,/\b(?:no phase change|without (?:a )?phase change|without changing phase|stays? (?:a )?liquid|remains? (?:a )?liquid|stays? (?:a )?solid|remains? (?:a )?solid|stays? (?:a )?gas|remains? (?:a )?gas)\b/i);
  const report = guide('calorimetry','Heat from a temperature change',
    'Find the heat transferred to or from the sample. Mass, specific heat, and the temperature change connect to that target.',
    'q = mcΔT   •   ΔT = Tfinal − Tinitial',[heatSource,conversion],
    [...masses.map(x=>given(x,'Mass of the material')), ...specificHeats.map(x=>given(x,'Heat required per mass per degree')),
      ...temperatures.map((x,i)=>given(x,i===0?'First stated temperature':'Second stated temperature')),
      condition(noPhase,'The sample stays in one phase'),target(desired,'Find heat transferred')]);
  const changedPhase = /\b(?:melt(?:s|ed|ing)?|boil(?:s|ed|ing)?|freez(?:e|es|ing)|froze|vapori[sz]\w*|condens(?:e|es|ed|ing))\b/i.test(input);
  if(changedPhase) return report(['Separate each temperature change from each phase change. Use mcΔT within one phase. Use the stated latent heat or phase-change enthalpy for the transition.'],
    {question:'Which phase changes occur, and what heat data are supplied for each one?'});
  if(!positive(mass)||!positive(c)||temperatures.length!==2)return report(['Write the mass, specific heat, initial temperature, and final temperature before substituting.'],
    {question:'Can you provide one sample mass, one specific heat, and both temperatures?'});
  const [start, end]=temperatures;
  const chronological=/\b(?:from|initial(?:ly)?|start(?:s|ed|ing)?)\b/i.test(input.slice(Math.max(0,start.index-42),start.index)) &&
    /\b(?:to|final(?:ly)?|end(?:s|ed|ing)?)\b/i.test(input.slice(start.end,end.index));
  if(!chronological)return report(['Subtract the starting temperature from the final temperature. The order determines the heat sign.'],
    {question:'Which temperature is initial and which is final?'});
  const delta=end.normalized-start.normalized;
  if((/\bwarm(?:s|ed|ing)?\b/i.test(input)&&delta<0)||(/\bcool(?:s|ed|ing)?\b/i.test(input)&&delta>0)){
    return report(['Check the stated direction. Warming increases temperature, and cooling decreases temperature.'],
      {question:'Which temperature should the sample change to?'});
  }
  const asMagnitude=/\bheat\b[\s\S]{0,22}\b(?:released|lost)\b/i.test(input)&&delta<0;
  const heat = mass.normalized*c.normalized*delta;
  const answer=answerNumber(input,heat,'J');
  const deltaLabel=/°C/.test(c.label)?'°C':'K';
  const facts=[stepLine(mass),start.label!==end.label?'First put both temperatures on the same scale. '+stepLine(start)+' '+stepLine(end):'',
    'Subtract the initial temperature from the final temperature. ΔT = '+expand(delta,deltaLabel)+'.',
    c.normalized!==c.value ? c.quote + ' = '+expand(c.normalized,'J/(g·'+deltaLabel+')')+'.' : '',
    expand(mass.normalized,'g')+' × '+expand(c.normalized,'J/(g·'+deltaLabel+')')+' × '+expand(delta,deltaLabel)+' = '+answer+'.',
    heat > 0 ? 'The positive sign means the sample absorbs heat.' :
      heat < 0 ? 'The negative sign means the sample releases heat'+(asMagnitude?' with a magnitude of '+answerNumber(input,-heat,'J'):'')+'.' :
        'The two temperatures are equal, so this temperature-change term is zero.'];
  if(!answer)return report(['Check the given amounts and units before multiplying.'],{question:'Can you confirm the measurements?'});
  return report([!noPhase?'For a single-phase change, use the supplied specific heat over this temperature interval.':null,...facts],
    {answer:asMagnitude?answerNumber(input,-heat,'J')+' released':answer,conditional:!noPhase, unitChain:[factor(line(display(mass.normalized),'g!')),
      factor(line(display(c.normalized),'J'),line(1,'g!',deltaLabel+'!')),factor(line(display(delta),deltaLabel+'!'))]});
}

function density(input, units) {
  const desired = find(input,/\b(?:(?:what(?: is|['’]s)|find|calculate|determine)\s+(?:the\s+)?density|how dense)\b/i);
  if(!desired)return null;
  const masses=units('mass'), volumes=units('volume');
  if(!masses.length&&!volumes.length)return null;
  const mass=one(masses);
  const displacement=find(input,/\b(?:displacement|displaces?|raises? (?:the )?(?:liquid|water) level|level rises?|completely submerged|fully submerged)\b/i);
  const report=guide('density','Density from mass and volume',
    'Density compares the mass of the sample with the space that same sample occupies. Start by identifying its actual volume.',
    'ρ = m / V',[chemistry('1-4-measurements','Density and measurement'),conversion],
    [...masses.map(x=>given(x,'Mass of the sample')), ...volumes.map(x=>given(x,displacement?'A liquid reading or displaced volume':'Volume stated in the problem')),
      condition(displacement,'Liquid displacement can indicate the sample volume'),target(desired,'Find density')]);
  if(!nonnegative(mass)||!volumes.every(positive)||(!displacement&&volumes.length!==1)||volumes.length>2){
    return report(['Find one mass and the volume of the sample. When given two liquid levels, find the difference first using the same units.'],
      {question:'Which mass and volume refer to the sample?'});
  }
  const [first,last]=volumes;
  if(!first)return report(['Divide the sample mass by its volume.'],{question:'What is the sample volume?'});
  if(last&&(!displacement||last.normalized<=first.normalized))return report(['For a fully submerged sample, subtract the initial liquid reading from the final liquid reading.'],
    {question:'Which reading was taken before the sample was submerged, and which was taken after?'});
  const vol=(last?last.normalized-first.normalized:first.normalized)*1000;
  const value=mass.normalized/vol;
  const result=answerNumber(input,value,'g/mL');
  if(!result)return report(['Check that the sample volume is greater than zero.'],{question:'Can you confirm the sample volume?'});
  return report([stepLine(mass),
    last?expand(last.normalized*1000,'mL')+' − '+expand(first.normalized*1000,'mL')+' = '+expand(vol,'mL')+'.':
      first.label!=='mL'?first.quote+' = '+expand(vol,'mL')+'.':'',
    expand(mass.normalized,'g')+' ÷ '+expand(vol,'mL')+' = '+result+'.'],
    {answer:result,unitChain:[factor(line(display(mass.normalized),'g'),line(display(vol),'mL'))]});
}

const gasTypes = ['pressure','volume','temperature','amount'];
const gasTargets = {
  pressure:/\b(?:find|what (?:is|will be)|calculate|determine)\s+(?:the\s+)?(?:final |new |resulting |initial )?(?:gas )?pressure\b/i,
  volume:/\b(?:find|what (?:is|will be)|calculate|determine)\s+(?:the\s+)?(?:final |new |resulting |initial )?(?:gas )?volume\b/i,
  temperature:/\b(?:find|what (?:is|will be)|calculate|determine)\s+(?:the\s+)?(?:final |new |resulting |initial )?(?:absolute )?temperature\b/i,
  amount:/\b(?:how many|find(?: the)?|calculate(?: the)?|determine(?: the)?)\s+(?:amount of |number of )?mol(?:es)?\b/i
};
const gasClues = {
  pressure:/\b(?:constant|same|fixed) pressure\b|\bpressure (?:stays|remains) (?:the same|constant|fixed)\b/i,
  volume:/\b(?:constant|same|fixed) volume\b|\bvolume (?:stays|remains) (?:the same|constant|fixed)\b|\brigid (?:tank|container)\b/i,
  temperature:/\b(?:constant|same|fixed) temperature\b|\btemperature (?:stays|remains) (?:the same|constant|fixed)\b|\bisothermal\b/i,
  amount:/\b(?:constant|same|fixed) (?:moles|amount|mass)(?: of (?:the )?gas)?\b|\bsealed\b|\b(?:amount|moles|mass)(?: of (?:the )?gas)? (?:stays|remains) (?:the same|constant|fixed)\b/i
};
const gasLetters={pressure:'P',volume:'V',temperature:'T',amount:'n'};

function gasLaws(input, units) {
  const labels=Object.fromEntries(gasTypes.map(kind=>[kind,units(kind)]));
  const recognized=/\b(?:gas(?: sample| law| laws| behaves)?|Boyle|Charles|Amontons|Gay[- ]Lussac|PV\s*=\s*nRT)\b/i.test(input);
  const targets=Object.entries(gasTargets).flatMap(([key,pattern])=>{
    const quote=find(input,pattern);return quote?[[key,quote]]:[];
  });
  if(!recognized||!targets.length||!gasTypes.some(kind=>labels[kind].length))return null;
  const [wanted, desired] = targets[0];
  const constants=Object.fromEntries(gasTypes.map(kind=>[kind,find(input,gasClues[kind])]));
  const twoStates=gasTypes.some(kind=>labels[kind].length===2)
    || /\b(?:compressed|expands?|expanded|warms?|cools?|heated|changes? to|new volume|new pressure|final volume|final pressure|final temperature)\b/i.test(input);
  const report=guide(twoStates?'combined-gas-law':'ideal-gas-law',twoStates?'A gas changing between two states':'One state of an ideal gas',
    twoStates?'Compare the starting and final gas states. Identify which quantities stay fixed before canceling them.':
      'Pressure, volume, amount, and absolute temperature describe a single gas state. Use the three given quantities to find the fourth.',
    twoStates?'P₁V₁/T₁ = P₂V₂/T₂ if the amount of gas is fixed':'PV = nRT',
    [gasSource,conversion],
    [...gasTypes.flatMap(kind=>labels[kind].map(x=>given(x,kind[0].toUpperCase()+kind.slice(1)+' stated in the problem'))),
      ...gasTypes.map(kind=>condition(constants[kind],(kind==='amount'?'Amount of gas':kind)+' stays fixed')),
      target(desired,'Find '+wanted)]);
  if (targets.length!==1||gasTypes.some(kind=>labels[kind].length>2||labels[kind].some(x=>!positive(x)))) {
    return report(['Identify one target and label every measurement with its gas state. All gas-state values used here must be positive.'],
      {question:'Which single gas quantity do you want to find?'});
  }
  if(!twoStates) {
    if(!/\b(?:ideal gas|behaves ideally|assume (?:an? )?ideal|PV\s*=\s*nRT|using (?:the )?ideal gas law)\b/i.test(input)){
      return report(['For a single gas state, the usual classroom starting point is PV = nRT under the ideal-gas approximation.'],
        {question:'Does the problem tell you to use the ideal gas law?'});
    }
    const known=Object.fromEntries(gasTypes.map(kind=>[kind,one(labels[kind])]));
    if(known[wanted]||gasTypes.some(kind=>kind!==wanted&&!positive(known[kind]))){
      return report(['List the three known values, convert the temperature to kelvin, and isolate the remaining variable.'],
        {question:'Which three values are provided for this gas state?'});
    }
    const {pressure:p,volume:v,temperature:t,amount:n}=Object.fromEntries(gasTypes.map(kind=>[kind,known[kind]?.normalized]));
    const r=8.314462618;
    const value=wanted==='amount'?p*v/(r*t):wanted==='volume'?n*r*t/p:wanted==='pressure'?n*r*t/v:p*v/(n*r);
    const answer=answerNumber(input,value,baseUnit[wanted]);
    const rightHand=wanted==='amount'?'PV / (RT)':wanted==='volume'?'nRT / P':wanted==='pressure'?'nRT / V':'PV / (nR)';
    if(!answer||value<=0)return report(['Check the sizes and units of the starting measurements.'],{question:'Can you confirm the given gas-state values?'});
    const pressure=line(display(p),'kPa!'), volume=line(display(v),'L!'), temperature=line(display(t),'K!');
    const mol=line(display(n),'mol!'), rTop=line(display(r),'kPa!','L!'), rBottom=line(1,'mol!','K!');
    const chain=wanted==='amount'?[factor(pressure),factor(volume),factor(line(1,'mol','K!'),rTop),factor(line(1),temperature)]:
      wanted==='volume'?[factor(mol),factor(line(display(r),'kPa!','L'),rBottom),factor(temperature),factor(line(1),pressure)]:
      wanted==='pressure'?[factor(mol),factor(line(display(r),'kPa','L!'),rBottom),factor(temperature),factor(line(1),volume)]:
      [factor(pressure),factor(volume),factor(line(1,'mol!','K'),rTop),factor(line(1),mol)];
    const substitution=gasTypes.filter(kind=>kind!==wanted).map(kind=>gasLetters[kind]+' = '+expand(known[kind].normalized,baseUnit[kind])).join(', ');
    return report(['For kPa, liters, and kelvin, use R = 8.314462618 kPa·L/(mol·K).',
      ...gasTypes.filter(kind=>kind!==wanted).map(kind=>stepLine(known[kind])),
      'Rearrange before substituting. '+gasLetters[wanted]+' = '+rightHand+'.',
      'Use '+substitution+'. '+gasLetters[wanted]+' = '+answer+'.'],
      {answer,unitChain:chain});
  }
  if(!constants.amount||/\b(?:gas (?:escapes?|leaks?)|(?:gas is )?(?:added|removed)|changing amount of gas|amount of gas changes)\b/i.test(input)) {
    return report(['Use the combined gas law only for a fixed amount of gas. If the amount changes, track the moles in each state.'],
      {question:'Does the amount of gas stay the same between states?'});
  }
  if(wanted==='amount'||constants[wanted]||/\binitial\b/i.test(desired))return report(['Mark the requested variable as initial or final and fill in the remaining values for each state.'],
    {question:'Which starting and final conditions does the problem give?'});
  const changing=gasTypes.slice(0,3).filter(kind=>!constants[kind]);
  if(changing.some(kind=>labels[kind].length!==(kind===wanted?1:2)) ||
    gasTypes.slice(0,3).some(kind=>constants[kind]&&labels[kind].length===2&&
      labels[kind][0].normalized!==labels[kind][1].normalized)) {
    return report(['Make an initial column and a final column for pressure, volume, and temperature. Cross out any quantity that stays fixed.'],
      {question:'Can you label each changing quantity as initial or final?'});
  }
  const targetIndex=input.search(gasTargets[wanted]);
  const startMeasures=changing.map(kind=>labels[kind][0]);
  const endMeasures=changing.filter(kind=>kind!==wanted).map(kind=>labels[kind][1]);
  const lastInitial=Math.max(...startMeasures.map(item=>item.end));
  const firstFinal=Math.min(...endMeasures.map(item=>item.index));
  // The simple prose form labels all initial values together and all final values together.
  // Ambiguous or interleaved state labels are clarified instead of inferred.
  if (!endMeasures.length || lastInitial>=firstFinal || (targetIndex>=0&&lastInitial>targetIndex&&
      endMeasures.some(item=>item.index<targetIndex))){
    return report(['List the measurements for each state together. This keeps initial conditions from being paired with final ones.'],
      {question:'Which measurements go together in the initial state?'});
  }
  const between=input.slice(lastInitial,firstFinal);
  if(!/\b(?:to|final|new|now|changes?|then|becomes?|reaches?|after|at|when)\b/i.test(between))return report(
    ['Make sure the first set of values belongs to the initial state and the second set belongs to the final state.'],
    {question:'Which values belong to the final state?'});
  const relative = kind=>constants[kind]?1:labels[kind][1].normalized/labels[kind][0].normalized;
  const scale=wanted==='volume'?relative('temperature')/relative('pressure'):
    wanted==='pressure'?relative('temperature')/relative('volume'):relative('pressure')*relative('volume');
  const initial=labels[wanted][0];
  const value=initial.normalized*scale;
  const answer=answerNumber(input,value,baseUnit[wanted]);
  if(!answer||value<=0)return report(['Check the measurements before applying the gas relationship.'],{question:'Can you confirm each pressure, temperature, and volume given?'});
  const ratioKinds=changing.filter(kind=>kind!==wanted);
  const ratios=ratioKinds.map(kind=>{
    const reverse=wanted!=='temperature'&&kind!=='temperature';
    return {kind,top:labels[kind][reverse?0:1],bottom:labels[kind][reverse?1:0],label:baseUnit[kind]};
  });
  const substitution=expand(initial.normalized,baseUnit[wanted])+ratios.map(({top,bottom,label})=>
    ' × (' + expand(top.normalized,label) + ' / ' + expand(bottom.normalized,label) + ')').join('');
  return report(['The amount stays fixed. Cancel any constant pressure, volume, or temperature from the comparison.',
    ...changing.flatMap(kind=>labels[kind].map(item=>stepLine(item))),
    substitution+' = '+answer+'.'],
    {answer,unitChain:[factor(line(display(initial.normalized),baseUnit[wanted])),
      ...ratios.map(({top,bottom,label})=>factor(line(display(top.normalized),label+'!'),line(display(bottom.normalized),label+'!')))]});
}

function mitoticIndex(input) {
  const desired=find(input,/\b(?:(?:what is|find|calculate|determine)\s+(?:the\s+)?mitotic index|mitotic index|(?:percent(?:age)?|proportion|fraction) of (?:the )?cells in mitosis)\b/i);
  if(!desired||!/\d/.test(input))return null;
  const unitName=/\b(?:percent(?:age)?|as a percent(?:age)?)\b|%/.test(input)?'%':'';
  const countPattern = /\b(\d+)\s+(?:of|out of)\s+(?:the\s+)?(\d+)\s+(?:(?:observed|counted|total|sampled?)\s+)?cells\b([^.!?;]{0,45})/i;
  const pair=input.match(countPattern);
  const explicitTotal=input.match(/\b(?:counted?|observed|sampled|total of)\s+(\d+)\s+cells\b|\b(\d+)\s+(?:cells\s+)?(?:in total|counted overall)\b/i);
  const explicitDividing=input.match(/\b(\d+)\s+(?:of (?:them|those)|cells)?\s*(?:(?:are|were)\s+)?(?:in mitosis|dividing)\b/i);
  const isMitotic=pair&&/\b(?:mitosis|dividing)\b/i.test(pair[3]);
  const total=isMitotic?Number(pair[2]):Number(explicitTotal?.[1]??explicitTotal?.[2]);
  const dividing=isMitotic?Number(pair[1]):Number(explicitDividing?.[1]);
  const report=guide('mitotic-index','Find the fraction of cells in mitosis',
    'The target is a share of the cells you counted. Put only cells in mitosis on top and all observed cells on the bottom.',
    'mitotic index = cells in mitosis / total cells counted',[indexSource],
    [isMitotic?{quote:pair[0].trim(),role:'Given',meaning:'This wording gives the mitotic count and the total'}:
      explicitDividing?{quote:explicitDividing[0],role:'Given',meaning:'Number in mitosis'}:null,
    !isMitotic&&explicitTotal?{quote:explicitTotal[0],role:'Given',meaning:'Number of cells counted overall'}:null,
    target(desired,unitName?'Find the percentage in mitosis':'Find the fraction in mitosis')].filter(Boolean));
  const pluralGroups=/\b(?:second field|slide [AB]|two (?:fields|samples|slides)|fields combined|pooled)\b/i.test(input);
  if(pluralGroups||!Number.isSafeInteger(total)||!Number.isSafeInteger(dividing)||total<=0||dividing<0||dividing>total){
    return report(['Count cells in mitosis for the numerator. For several fields, add the counts first and divide the combined counts.'],
      {question:'How many cells were in mitosis, and how many cells did you count altogether?'});
  }
  const fraction=dividing/total;
  return report(['Divide the two counts. '+dividing+' / '+total+' = '+display(fraction)+'.',
    'Multiply the fraction by 100 if you need a percent. '+answerNumber(input,100*fraction,'%')+' of the cells were in mitosis.'],
    {answer:answerNumber(input,unitName?100*fraction:fraction,unitName)});
}

function hardyWeinberg(input, units) {
  const desired=find(input,/\b(?:what (?:fraction|percent(?:age)?|proportion)\s+(?:of (?:the )?population\s+)?(?:are|is|will be)\s+(?:expected\s+)?(?:carriers?|heterozygous)|(?:carrier|heterozygote|heterozygous) frequency|(?:frequency|percentage) of (?:carriers?|heterozygotes?)|(?:find|calculate|determine)\s+(?:the\s+)?(?:[pq] (?:and [pq])?|(?:dominant|recessive) allele frequency))\b/i);
  const recognized=/\b(?:Hardy[–— -]+Weinberg|recessive phenotype|q\s*[²^])\b/i.test(input);
  if(!desired||!recognized||!/\d/.test(input))return null;
  const percent=one(units('percent'));
  const equilibrium=find(input,/\b(?:in|under|assum(?:e|ing)(?: the population is in)?)\s+Hardy[–— -]+Weinberg(?: equilibrium)?\b|\bat (?:genetic )?equilibrium\b|\bHardy[–— -]+Weinberg equilibrium\b/i);
  const describedRecessive=find(input,/\brecessive phenotype\b|\bshow(?:s|ing)? (?:the )?recessive trait\b|\bhave(?:s)? (?:the )?recessive (?:trait|phenotype)\b|\b(?:homozygous recessive|recessive genotype)\b/i);
  const valueEnd='(?![0-9A-Za-z]|\\.\\d)';
  const qSq=input.match(new RegExp('\\bq(?:²|\\^?2)\\s*=\\s*('+numberPattern+')'+valueEnd,'i'));
  const qAssigned=input.match(new RegExp('\\bq\\s*=\\s*('+numberPattern+')'+valueEnd,'i'));
  const pAssigned=input.match(new RegExp('\\bp\\s*=\\s*('+numberPattern+')'+valueEnd,'i'));
  const report=guide('hardy-weinberg','Alleles and carriers under Hardy–Weinberg',
    'Separate the frequency of an allele from the fraction of individuals with a particular genotype. For this model, p and q are allele frequencies.',
    'p + q = 1   •   p² + 2pq + q² = 1',[populationSource],
    [percent?given(percent,'A percentage whose genotype or allele label matters'):null,
      ...[qSq,qAssigned,pAssigned].filter(Boolean).map(match=>({quote:match[0],role:'Given',meaning:'An explicitly labeled model value'})),
      condition(equilibrium,'The problem invokes Hardy–Weinberg equilibrium'),
      condition(describedRecessive,'A recessive phenotype corresponds to q² in the simple complete-dominance model'),
      target(desired,/carrier|heterozyg/i.test(desired)?'Find the expected share of heterozygotes':'Find the allele frequency')].filter(Boolean));
  if(!equilibrium)return report(['Hardy–Weinberg describes an expectation under its equilibrium assumptions. The same observed percentages can have different causes outside that model.'],
    {question:'Does the problem ask you to assume Hardy–Weinberg equilibrium?'});
  if([qSq,qAssigned,pAssigned].filter(Boolean).length>1 || units('percent').length>1 || /\b(?:sex.linked|x.linked|multiple alleles|incomplete dominance|codominance)\b/i.test(input)){
    return report(['Label each given number as an allele frequency or a genotype frequency. This setup uses a single locus with two alleles.'],
      {question:'Which one frequency and inheritance model does the problem give?'});
  }
  let q, origin;
  if(qSq&&!percent){
    const squared=numeric(qSq[1]);
    q=squared>=0&&squared<=1?Math.sqrt(squared):NaN;
    origin='Take the square root of the given q². q = √'+qSq[1]+' = '+display(q)+'.';
  }else if(qAssigned&&!percent){
    q=numeric(qAssigned[1]);origin='The given number is already q, the frequency of the recessive allele.';
  }else if(pAssigned&&!percent){
    const p=numeric(pAssigned[1]);q=1-p;origin='Subtract the given p from 1. q = 1 − '+pAssigned[1]+' = '+display(q)+'.';
  }else if(percent && (describedRecessive || qSq)) {
    const squared=percent.value/100;
    q=squared>=0&&squared<=1?Math.sqrt(squared):NaN;
    origin='For the simple recessive phenotype, q² = '+display(squared)+'. Take the square root to get q = '+display(q)+'.';
  }
  if(!Number.isFinite(q)||q<0||q>1)return report(['An allele frequency is already p or q. With complete dominance, the recessive phenotype frequency is q², so take its square root.'],
    {question:'Is the given number an allele frequency, or the share of people or organisms with the recessive phenotype?'});
  const p=1-q, carriers=2*p*q;
  const requestedCarriers=/carrier|heterozyg/i.test(desired);
  const requestedP=/\b(find|calculate|determine) p\b|\bdominant allele frequency\b/i.test(desired);
  const both=/\b[qp] and [pq]\b/i.test(desired);
  const percentTarget=/\b(?:percent(?:age)?)\b/i.test(desired);
  const result=both?'p = '+answerNumber(input,p,'')+' and q = '+answerNumber(input,q,''):
    requestedCarriers?answerNumber(input,percentTarget?100*carriers:carriers,percentTarget?'%':''):
      answerNumber(input,requestedP?p:q,'');
  return report([origin,'Find the other allele frequency using p = 1 − q = '+display(p)+'.',
    requestedCarriers?'Expected carriers are heterozygotes. 2pq = 2 × '+display(p)+' × '+display(q)+' = '+display(carriers)+
      ', or '+answerNumber(input,100*carriers,'%')+'.':'Check that p + q = 1.'],
    {answer:result});
}

function percentChange(input, units) {
  const desired=find(input,/\b(?:percent(?:age)? (?:change|increase|decrease|gain|loss)|by what percent(?:age)?|what percent(?:age)? did[^.!?]{0,55}\b(?:grow|change|increas\w*|decreas\w*))\b/i);
  if(!desired||!/\d/.test(input))return null;
  const linked=input.match(new RegExp('\\bfrom\\s+('+numberPattern+')\\s*(?:[A-Za-z°³]+\\s+){0,2}to\\s+('+numberPattern+')(?![\\d.])','i'));
  const measurements=['mass','volume','pressure','amount','concentration','temperature'].flatMap(units).sort((a,b)=>a.index-b.index);
  const matches=linked&&measurements.length===2&&measurements[0].kind===measurements[1].kind;
  const mixed=measurements.length>0&&!matches;
  const counts=linked&&!mixed?[numeric(linked[1]),numeric(linked[2])]:[];
  const [first,last]=matches?measurements.map(item=>item.normalized):counts;
  const report=guide('percent-change','Compare a change with its starting value',
    'Find the amount of change first. Then divide by the starting value to compare the change to what you had at the beginning.',
    'percent change = [(final − initial) / initial] × 100%',
    [conversion,biology('45-1-population-demography','Population data')],
    [linked?{quote:linked[0],role:'Given',meaning:'The first measurement is the baseline and the second is the later value'}:null,
      ...measurements.map(item=>given(item,'A measured value to compare')),target(desired,'Find percent change')].filter(Boolean));
  if(!finite(first)||!finite(last)||first<=0||last<0||(matches&&measurements[0].kind==='temperature')){
    return report(['Write the initial and final values in the same unit. Divide by the initial value only when it is a meaningful, positive baseline.'],
      {question:'What are the before-and-after values, including the same unit for both?'});
  }
  const change=last-first;
  const value=100*change/first;
  const answer=answerNumber(input,value,'%');
  if(!answer)return report(['Check the starting and final values before calculating.'],{question:'Can you confirm the two values?'});
  return report([...(matches?measurements.map(item=>stepLine(item)):[]),
    'Final minus initial gives '+display(last)+' − '+display(first)+' = '+display(change)+'.',
    '('+display(change)+' / '+display(first)+') × 100% = '+answer+'.',
    value===0?'The final value is the same as the initial value.':value>0?'The positive sign means an increase.':'The negative sign means a decrease.'],
    {answer});
}

export function explainLearnerProblem(input) {
  if(typeof input!=='string'||input.length>3000||!/[0-9]/.test(input))return null;
  const text=input.trim();
  // Exclude follow-up and navigation requests from the standalone problem parser.
  if(/^(?:where did|how did (?:you|we) get|what if|what about|instead use|change it|show me (?:a |another )?(?:sample|practice)|give me (?:a |another )?(?:sample|practice|word)|can you give me an example)\b/i.test(text))return null;
  const values=parseMeasures(text);
  const units=kind=>values.filter(item=>item.kind===kind);
  const methods=[mitoticIndex,hardyWeinberg,percentChange,calorimetry,concentration,gasLaws,density,massMoles];
  for(const solve of methods){
    const result=solve(text,units);
    if(!result)continue;
    if(!result.answer)return result;
    const converted=new Set(result.steps);
    const conversions=[];
    for(const item of values){
      const label=baseUnit[item.kind];
      if(!label||item.label===label||!converted.has(stepLine(item,label)))continue;
      if(item.offset){
        conversions.push({label:'Convert '+item.quote+' to '+label,
          formula:'T(K) = T(°C) + 273.15',result:expand(item.normalized,label)});
        continue;
      }
      const ratio=item.label==='torr'?[101.325,760]:item.scale>=1?[item.scale,1]:[1,1/item.scale];
      conversions.push({label:'Convert '+item.quote+' to '+label,
        chain:[factor(line(item.raw,item.label+'!')),factor(line(display(ratio[0]),label),line(display(ratio[1]),item.label+'!'))],
        result:convertedValue(item,label)});
    }
    return {...result,unitWork:[...conversions,...(result.unitWork??[])]};
  }
  return null;
}

const followupValue = new RegExp('(?<![A-Za-z0-9.])(' + numberPattern + ')(?![0-9]|\\.\\d)', 'g');
const valuesIn = text => [...String(text??'').replace(/(\d),(?=\d{3}\b)/g,'$1').matchAll(followupValue)]
  .map(match=>numeric(match[1])).filter(Number.isFinite);
const includesValue = (text,value) => valuesIn(text).some(number=>Object.is(number,value)||Math.abs(number-value)<=
  Math.max(Math.abs(number),Math.abs(value),1)*1e-10);

export function explainProblemFollowup(input, problem, cursor = 0) {
  const query = String(input).trim();
  const asksOrigin=/\b(?:where did|where does|how (?:did|do) (?:you|we|i) get|how (?:is|was) .+ calculated|how (?:did|do) (?:you|we|i) get to)\b/i.test(query);
  const asksOperation=/\bwhy\b[\s\S]{0,44}\b(?:divide|divided|multiply|multiplied|cancel|flip|subtract|subtracted|round|rounded|convert|converted)\b/i.test(query);
  const asksNext=/^(?:what(?:['’]s| is) (?:the )?next (?:step|part)|next step|what next|then what)\b/i.test(query);
  const asksWork=/^(?:(?:can|could|would) you )?(?:please )?(?:break (?:it|this|that|the problem) down|walk me through (?:it|this|that|the problem)|show (?:me )?(?:the |your )?(?:work|formula|equation|calculations?|math|steps)|explain (?:it|this|that) again|i (?:still )?don['’]?t (?:get|understand) (?:it|this|that))\b/i.test(query);
  if(!asksOrigin&&!asksOperation&&!asksNext&&!asksWork)return null;
  const {topic,title,links,steps,formula} = problem;
  const report=(text,details={})=>({topic,title,links,intent:'followup',text,...details});
  const [asked]=valuesIn(query);
  const conversion=problem.unitWork?.find(item=>asked!==undefined&&
    (includesValue(item.result,asked)||item.chain?.some(row=>[row.top,row.bottom].some(value=>
      value&&includesValue(value.value,asked)&& !includesValue(item.label,asked)))));
  if(conversion&&(asksOrigin||asksOperation)){
    const step=steps.find(line=>includesValue(line,asked));
    return report(asksOperation?'We do this conversion so the units fit the formula.':
      'That value comes from this conversion in your problem.',{unitWork:[conversion],steps:step?[step]:[]});
  }
  if(asksOperation){
    if(topic==='hess-law'&&/\b(?:reverse|reversing|flip|sign)\b/i.test(query))
      return report('Reversing swaps the start and end. The forward step takes Hfinal minus Hinitial. The reversed step subtracts them in the opposite order, so −283 kJ becomes +283 kJ.',
        {formula:'ΔH°reverse = −ΔH°forward',steps:steps.filter(line=>line.includes('Reverse the second reaction'))});
    if(topic==='molarity'&&/\b(?:divide|divided|division)\b/i.test(query)&&/\bM\s*=\s*n\s*\//.test(formula))
      return report('Molarity means moles of solute per liter of solution. Divide the solute amount by the final volume in liters to find the amount in one liter.',
        {formula,unitChain:problem.unitChain,steps:steps.filter(line=>/÷| = .*M\.?$/u.test(line)).slice(-2)});
    if(topic==='moles'&&/\b(?:divide|divided|multiply|multiplied|cancel)\b/i.test(query))
      return report(/\bn\s*=\s*m\s*\//.test(formula)?
        'There are that many grams in one mole. Dividing the starting grams by grams per mole leaves moles.':
        'Each mole weighs the molar mass in grams. Multiplying by grams per mole cancels moles and leaves grams.',
      {formula,unitChain:problem.unitChain,steps:steps.slice(-1)});
    if(topic==='mitotic-index')
      return report(/\b(?:multiply|multiplied|percent)\b/i.test(query)?
        'Multiplying the fraction by 100 expresses it as a percent, or how many per 100 cells.':
        'We divide by every counted cell because the mitotic index describes what share of the entire sample was in mitosis.',
      {formula,steps});
    if(topic==='percent-change'&&/\b(?:divide|divided)\b/i.test(query))
      return report('The initial value is the baseline. Dividing the change by that baseline tells you what fraction of the starting amount changed.',
        {formula,steps});
    const calculation=steps.find(line=>asked!==undefined&&includesValue(line,asked))??steps.at(-1);
    return report('Use this line of your calculation to check how the givens connect to the target.',
      {formula,steps:calculation?[calculation]:[],unitChain:problem.unitChain});
  }
  if(asksOrigin){
    const literal=problem.parts?.find(part=>part.role==='Given'&&asked!==undefined&&includesValue(part.quote,asked));
    if(literal)return report('That number is supplied in your problem. '+literal.meaning+'.',{parts:[literal]});
    const calculation=steps.find(line=>asked!==undefined&&includesValue(line,asked)&&/\b=|[=÷×√]/u.test(line));
    if(calculation)return report('That number is calculated in this step.',{formula,steps:[calculation]});
    if(asked===undefined)return report('Here is the calculation that produced the result.',
      {formula,steps:[...steps.filter(line=>/[=÷×√]/u.test(line)).slice(-2)],unitChain:problem.unitChain,answer:problem.answer});
    return report('Point me to the line or unit you want to trace.',{question:'Which step contains that number?'});
  }
  if(asksNext){
    const current=steps[Math.min(cursor,steps.length-1)];
    return report(current??'Start by labeling what the problem asks for.',{formula});
  }
  if(/\b(?:formula|equation)\b/i.test(query))return report('This is the relationship used for your problem.',{formula,steps:steps.slice(0,1)});
  return {...problem,intent:'followup',text:'Let’s work through the exact numbers in your problem.'};
}

