  return {row,order,names:[...new Set(names)],links:linksFor(row)};
});
const dictionary = new Set(entries.flatMap(entry => entry.names.flatMap(name => name.split(' ')))
  .filter(word => word.length >= 6 && /^[a-z]+$/.test(word)));

function oneEdit(a,b) {
  if(a===b||Math.abs(a.length-b.length)>1)return false;
  if(a.length!==b.length){
    const [short,long]=a.length<b.length?[a,b]:[b,a];
    let i=0;
    while(i<short.length&&short[i]===long[i])i++;
    return short.slice(i)===long.slice(i+1);
  }
  const differences=[];
  for(let i=0;i<a.length;i++)if(a[i]!==b[i])differences.push(i);
  const [i,j]=differences;
  return differences.length===1 || (differences.length===2&&j===i+1&&a[i]===b[j]&&a[j]===b[i]);
}

export function correctLearnerSpelling(query) {
  return query.replace(/\b[A-Za-z]{3,}\b/g,word=>{
    // Keep formulas, symbols, and all-caps abbreviations intact.
    if(/[A-Z]/.test(word.slice(1)))return word;
    const key=word.toLowerCase();
    if(Object.hasOwn(namedTypos,key))return namedTypos[key];
    if(key.length<6||dictionary.has(key)||plurals.has(key))return word;
    const options=[...dictionary].filter(term=>term[0]===key[0]&&oneEdit(key,term));
    return options.length===1?options[0]:word;
  });
}

export function learnerIntent(input,hasContext=false) {
  const text=phrase(input);
  if(/\b(?:difference|different from|compare|compared (?:with|to)|versus|vs|same (?:thing )?as|how can i tell|part of .+ or)\b/.test(text))return 'compare';
  if(/\bbalanc(?:e|ing)\b.*\b(?:equation|reaction)\b/.test(text))return 'approach';
  if(/\b(?:why|what is the point|what s the point|important|matter|useful|purpose)\b/.test(text)&&!/^why do (?:i|we) get \d/.test(text))return 'importance';
  if(/\b(?:equation|formula)\b|\bwhat does .{1,5} stand for\b/.test(text)&&!/^how (?:do|should) i (?:find|figure out|calculate) .*(?:empirical|molecular) formula/.test(text))return 'formula';
  if(/\b(?:stages?|phases?|sequence|in what order|comes (?:first|next|after)|goes first|what happens in each)\b/.test(text))return 'sequence';
  if(/\b(?:word problem|solve|calculate|approach|set up|how do i (?:start|work|do|find|figure out|get)|what do i do first|where do i start|what law do i use|how to (?:tell|do|find|solve))\b/.test(text))return 'approach';
  if(/\b(?:break (?:it|this|that|\w+) down|in plain (?:english|words)|in simple (?:terms|words)|simpler|simplify|don t (?:get|understand)|confused|lost)\b/.test(text))return 'simplify';
  if(/\b(?:example|in real life|show me one)\b/.test(text))return 'example';
  if(/\b(?:how (?:does|do|can|is|are)|what happens|what .+ does|how it works|what .+ do)\b/.test(text))return 'mechanism';
  if(hasContext&&/^(?:and |ok |okay )?(?:next|next step|go on|then what|what next|another way|more detail|explain more|explain it|show me how)(?: please)?$/.test(text))return 'followup';
  return 'definition';
}

function rank(text,course,intent) {
  return entries.flatMap(entry=>{
    const names=entry.names.filter(name=>bounded(text,name));
    if(!names.length)return [];
    const strong=Math.max(...names.map(name=>name.split(' ').length*100+name.length));
    const fit=entry.row.courses?.includes(course)?3:0;
    const wantsMethod=intent==='formula'||intent==='approach';
    const methodBonus=wantsMethod&&entry.row.method?28:!wantsMethod&&!entry.row.method?12:0;
    const generic=entry.row.id==='word-problems'?300:0;
    return [{entry,name:names.sort((a,b)=>b.length-a.length)[0],score:strong+fit+methodBonus-generic}];
  }).sort((a,b)=>b.score-a.score||a.entry.order-b.entry.order);
}

const promptRoot='/data/learner-prompts/v1/';
const cached=new Map();
async function readPromptFile(fetcher,path) {
  if(cached.has(path))return cached.get(path);
  const request=fetcher(promptRoot+path,{signal:AbortSignal.timeout(3500)}).then(async response=>{
    if(!response.ok)throw Error('Prompt lookup could not load');
    return new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json();
  }).catch(error=>{cached.delete(path);throw error;});
  cached.set(path,request);
  if(cached.size>16)cached.delete(cached.keys().next().value);
  return request;
}

