export function createLearnerTutor({fetcher=fetch,resolvePrompt}={}) {
  let context=null, pasted=null, step=0, pastedStep=0;
  const reset=()=>{context=null;pasted=null;step=0;pastedStep=0;};
  const remember=entry=>{if(context!==entry){context=entry;step=0;}};
  const report=(topic,intent,text,extra={})=>({topic,intent,text,...extra});
  async function respond(raw,course='',{hasSavedProblem=false}={}) {
    const input=String(raw).trim();
    if(/\b(?:published|external|openstax)\b.*\b(?:practice|problem|exercise|question)\b/i.test(input)
      ||/^where (?:can|should) i find (?:more |published )?(?:practice|practice questions|word problems)[?.! ]*$/i.test(input)){
      return report('published-practice','source','These publisher exercise pages cover common Biology and Chemistry topics.',
        {links:publishedPractice});
    }
    if(!input||navigation.test(input))return null;
    if(/\bhess(?:['’]s|s)?\s+law\b/i.test(input)&&/\b(?:worked example|work through an example|example with work)\b/i.test(input)){
      reset();
      pasted={...hessExample};
      return pasted;
    }
    if(practice.test(input))return null;
    if(/^\s*(?:new (?:problem|question|topic)|start over|forget (?:this|it|that))/i.test(input)){reset();return null;}
    const corrected=correctLearnerSpelling(input);
    let cleaned=phrase(corrected);
    if(hasSavedProblem&&/\b(?:why did you (?:divide|multiply|flip)|how did you get|where did .+ come from|break (?:this|it|that) down)\b/i.test(corrected))return null;
    if(pasted){
      const explanation=explainProblemFollowup(corrected,pasted,pastedStep);
      if(explanation){
        if(/^(?:what(?:['’]s| is) (?:the )?next (?:step|part)|next step|what next|then what)\b/i.test(corrected))pastedStep++;
        return explanation;
      }
    }
    const worked=explainLearnerProblem(input);
    if(worked){
      reset();
      pasted={...worked,actions:[['Break it down','Can you break it down?'],['Show the calculation','Show your work']]};
      return pasted;
    }
    pasted=null;
    const changesAll=/\bpressure\b/.test(cleaned)&&/\bvolume\b/.test(cleaned)&&/\b(?:temp|temperature)\b/.test(cleaned)&&/\b(?:all change|all vary|each change)\b/.test(cleaned);
    const subscriptQuestion=/\blittle numbers\b.*\bbalanc/.test(cleaned);
    const factorDirection=/\b(?:cancel|upside down|flip)\b/.test(cleaned)&&/\b(?:conversion|dimensional|fraction|unit)\b/.test(cleaned);
    const heatSign=/\b(?:heat q|q heat|sign of q)\b/.test(cleaned)&&/\b(?:positive|negative|sign)\b/.test(cleaned);
    const reverseEnthalpy=/\b(?:flip|reverse)\b.*\b(?:delta h|enthalpy)\b/.test(cleaned);
    if(/\blittle numbers\b.*\bbalanc|\bbalanc(?:e|ing)\b.*\b(?:equation|reaction)\b/.test(cleaned))cleaned+=' balancing equation balancing chemical equation';
    if(/\b(?:temperature|temp)\b.*\b(?:stays the same|constant|fixed)\b.*\b(?:container|volume|pressure)\b/.test(cleaned))cleaned+=' boyle law';
    if(changesAll)cleaned+=' combined gas law';
    if(reverseEnthalpy)cleaned+=' hess law';
    if(/\b(?:heat q|q heat|sign of q)\b/.test(cleaned))cleaned+=' calorimetry';
    if(/\bmark(?:s|ed|ing)?\b.*\b(?:catch|catching|caught)\b/.test(cleaned))cleaned+=' mark and recapture';
    if(/\brespiration\b.*\bbreathing\b/.test(cleaned))cleaned+=' cellular respiration';
    if(/\b(g|gram|mass)\s+(?:to\s+)?(mole|mol)\b|\b(mole|mol)\s+(?:to\s+)?(g|gram|mass)\b/.test(cleaned))cleaned+=' mole conversion';
    if(/\bmol ratio\b/.test(cleaned))cleaned+=' mole ratio';
    if(/\b(?:g 1 s g 2|g 1 g 2)\b/.test(cleaned)&&!bounded(cleaned,'cell cycle'))cleaned+=' interphase';
    if(/\b(?:sig fig|sig figs|significant figure)\b/.test(cleaned)&&/\bhow many\b/.test(cleaned)){
      const measurement=input.match(/(?<![\w.])([+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?)(?![\w.])/i)?.[1];
      const count=measurement&&countSigfigs(measurement);
      if(count)return report('significant-figures','approach',measurement+' has '+count+' significant figure'+(count===1?'':'s')+'.',
        {steps:['Zeros before the first nonzero digit are placeholders.','Zeros between significant digits count. Trailing zeros after a decimal point count.'],
          links:[['OpenStax · Measurement Uncertainty','https://openstax.org/books/chemistry-2e/pages/1-5-measurement-uncertainty-accuracy-and-precision']]});
    }
    if(/\bCo\b/.test(input)&&/\bCO\b/.test(input)){
      return report('chemical-formulas','compare','Co is the element symbol for cobalt. CO is the formula for carbon monoxide, with one carbon atom and one oxygen atom. A charge has to be shown or given separately, such as Co²⁺.',
        {links:[['OpenStax · Chemical Formulas','https://openstax.org/books/chemistry-2e/pages/2-4-chemical-formulas']]});
    }
    if(/\bmiosis\b/.test(cleaned)&&!bounded(cleaned,'mitosis')&&!bounded(cleaned,'meiosis')){
      return report(null,'clarify','Did you mean mitosis, which makes two daughter cells, or meiosis, which makes cells with half the chromosome sets?',
        {actions:[['Mitosis','What are the stages of mitosis?'],['Meiosis','What is meiosis?']]});
    }
    let intent=learnerIntent(corrected,!!context);
    if(/\b(?:monomer.+polymer|polymer.+monomer|lipid.+polymer)\b/.test(cleaned))intent='compare';
    if(/\bpercent change\b/.test(cleaned)&&intent==='definition'&&/^explain how/.test(cleaned))intent='approach';
    const ranked=rank(cleaned,course,intent);
    const wantsPurpose=/\b(?:why|important|matter|purpose)\b/.test(cleaned);
    const wantsExample=/\bexample\b/.test(cleaned);
    const wantsPlain=/\b(?:break (?:it|this|that) down|in simple (?:terms|words)|in plain (?:english|words))\b/.test(cleaned);
    const comparesMonomers=intent==='compare'&&bounded(cleaned,'monomer')&&bounded(cleaned,'polymer');
    const comparesGroups=intent==='compare'&&bounded(cleaned,'hydroxyl')&&bounded(cleaned,'carboxyl');
    const found=changesAll?entries.find(item=>item.row.id==='combined-gas-law'&&item.row.method)
      :comparesMonomers?entries.find(item=>item.row.id==='monomer-polymer')
      :comparesGroups?entries.find(item=>item.row.id==='functional-groups')
      :bounded(cleaned,'interphase')&&(bounded(cleaned,'mitosis')||bounded(cleaned,'cell cycle'))&&intent==='compare'
        ?entries.find(item=>item.row.id==='interphase'):ranked[0]?.entry;
    const numberFollow=/\b(?:where did|how did|how do you)\b.*\b(?:get|find|come from)\b/i.test(input)&&/\d/.test(input);
    if(numberFollow&&hasSavedProblem)return null;
    const words=learnerWords(cleaned);
    const contextual=!found&&context&&words.length<=17&&(
      intent==='simplify'||intent==='followup'||numberFollow||(wantsPurpose&&wantsPlain)||/\b(?:why you (?:divided|multiplied|flipped)|why (?:did|do) you (?:divide|multiply|flip))\b/.test(cleaned)||
      /^(?:and |ok |okay )?(?:why(?: does (?:it|that) matter| is (?:it|that) important)?|how(?: does (?:it|that) work)?|what about (?:it|that)|can you explain (?:this|it|that)|(?:show|give) me (?:the (?:formula|equation|steps)|an example)|what (?:(?:is|s) the (?:formula|equation)|(?:formula|equation) (?:do|should) i use)|help me (?:solve|work (?:on|through)) (?:this|it)|how (?:do|should) i (?:solve|approach|start) (?:this|it)|can you break (?:it|that|this) down)(?: please| though)?$/.test(cleaned)
    );
    const entry=found||(contextual?context:null);
    if(entry){
      let {row,links}=entry;
      const alternate=ranked.find(candidate=>candidate.entry.row.id!==row.id&&candidate.name!==ranked[0]?.name)?.entry;
      const courseId=row.courses?.[0]??course;
      let chosen=intent;
      if(contextual&&row.id&&intent==='definition'&&/\bwhy\b/.test(cleaned))chosen='importance';
      if(contextual&&intent==='definition'&&/\bhow\b/.test(cleaned))chosen='mechanism';
      if(chosen==='formula'&&!row.formula&&contextual){
        const richer=rank(phrase(row.title),course,'formula').find(candidate=>candidate.entry.row.formula);
        if(richer){row=richer.entry.row;links=richer.entry.links;}
      }
      remember(entry);
      const title=row.title;
      const actions=[['Break it down','Can you break it down?'],['Why it matters','Why does it matter?']];
      if(row.formula)actions.push(['Show the formula','What is the formula?']);
      if(row.example)actions.push(['Show an example','Show me an example']);
      const base={title,course:courseId,links,actions,matched:ranked[0]?.name};
      if(subscriptQuestion)return report('balancing-equations','importance',
        'The little numbers are subscripts. Changing a subscript changes which compound the formula names. Change the coefficient in front of a whole formula to count more or fewer copies of that substance.',
        {...base,example:'Changing 2 H₂O to H₂O₂ replaces water with hydrogen peroxide. Use coefficients and count each element on both sides.'});
      if(factorDirection)return report('dimensional-analysis','approach',
        'Put the starting unit on the bottom of the conversion fraction. That puts it opposite the same unit on top in the starting amount. The unit you want goes on top and stays in the result.',
        {...base,formula:'Old quantity × (new unit / old unit) = quantity in the new unit',example:row.example});
      if(heatSign)return report('calorimetry','approach',
        'For the object you are tracking, positive q means it absorbed heat. Negative q means it released heat. In q = mcΔT, a temperature increase gives positive ΔT, while a decrease gives negative ΔT.',
        {...base,formula:'q = mcΔT    ΔT = Tfinal − Tinitial'});
      if(reverseEnthalpy)return report('hess-law','importance',
        'When you reverse a reaction, you swap the starting and ending states. The energy change reverses too. A step that released 25 kJ in the forward direction absorbs 25 kJ in the reverse direction.',
        {...base,formula:'ΔHreverse = −ΔHforward'});
      if(numberFollow){
        return report(row.id,'followup','Here is the example we are working from. Which line or unit would you like to check?',
          {...base,example:row.example});
      }
      if(chosen==='compare'&&row.compare)return report(row.id,chosen,
        wantsPurpose&&row.why?row.why+' '+row.compare:row.compare,
        {...base,example:wantsExample?(row.id==='monomer-polymer'?
          'Glucose units join to make starch. Amino acid building blocks join to make a protein.':row.example):undefined});
      if(chosen==='compare'&&row.id==='interphase')return report(row.id,chosen,'Interphase is part of the cell cycle. It happens before mitosis. During interphase, the cell grows and copies its DNA. During mitosis, the copied chromosomes separate into new nuclei.',base);
      if(chosen==='compare'&&alternate&&
        !['monomer-polymer','cell-cycle','dehydration-hydrolysis'].includes(row.id)){
        return report(row.id,chosen,'Here’s how to tell them apart.',
          {...base,links:[...links,...alternate.links],steps:[title+' — '+row.answer,alternate.row.title+' — '+alternate.row.answer]});
      }
      if(chosen==='formula'){
        if(row.id==='word-problems')return report(row.id,'approach','Start with the quantity you need to find. Then list the given values, units, and conditions that connect to it.',
          {...base,steps:setup,question:'Paste the problem so we can choose a relationship from its clues.'});
        const compare=/\b(?:or|instead of)\b/.test(cleaned)&&alternate?.row.formula;
        if(compare)return report(row.id,chosen,'Choose the equation by what you need to find.',
          {...base,links:[...links,...alternate.links],steps:[title+' — '+row.formula,alternate.row.title+' — '+alternate.row.formula]});
        return report(row.id,chosen,row.answer,{...base,formula:row.formula,steps:row.steps?.slice(0,row.formula?2:undefined)});
      }
      if(chosen==='approach')return report(row.id,chosen,row.answer,{...base,
        steps:row.id==='word-problems'?setup:row.steps??setup,formula:row.formula,question:'Which quantities are given, and what are you being asked to find?'});
      if(chosen==='sequence'||chosen==='mechanism')return report(row.id,chosen,row.answer,{...base,steps:row.steps});
      if(chosen==='importance')return report(row.id,chosen,
        wantsPlain&&row.simple?(row.why??row.answer)+' '+row.simple:row.why??row.answer,
        {...base,example:wantsPlain?undefined:row.example,steps:wantsPlain&&!row.simple?row.steps?.slice(0,3):
          row.method&&/\b(?:divide|divided|cancel|reverse|flip|sign|why does)\b/.test(cleaned)?row.steps:undefined});
      if(chosen==='example')return report(row.id,chosen,row.example??row.answer,{...base,formula:row.formula});
      if(chosen==='simplify')return report(row.id,chosen,row.simple??row.analogy??row.answer,
        {...base,steps:row.simple?undefined:row.steps?.slice(0,3),example:row.simple?undefined:row.example});
      if(chosen==='followup'){
        const next=row.steps?.[step++];
        return report(row.id,chosen,next??row.example??row.answer,{...base,formula:row.formula,next:!!row.steps?.[step]});
      }
      return report(row.id,chosen,row.answer,base);
    }
    if(/\b(?:word problem|how (?:do|should) i (?:approach|start|solve|work on) (?:this|it)|help me solve (?:this|it)|how do i do (?:this|it))\b/.test(cleaned)&&!hasSavedProblem){
      return report('word-problem','approach','Start with the target. Then look for which details help you reach it.',
        {steps:setup,question:'Paste the problem and highlight the part where you got stuck.'});
    }
    if((/^(?:i (?:still )?don t (?:get|understand)(?: this| it)?|how does (?:it|that) work|why does (?:it|that) matter|what (?:is|s) the (?:equation|formula)|which (?:equation|formula) (?:do|should) i use)(?: please)?$/.test(cleaned)||
      /^(?:can you )?break (?:this|it|that) down\b/.test(cleaned))&&!hasSavedProblem){
      return report(null,'clarify','Which topic or step should we unpack? You can paste the sentence or problem that tripped you up.');
    }
    const lookup=resolvePrompt??(async key=>{
      const match=(await readPromptFile(fetcher,'prompt/'+bucketFor(key)+'.bin'))[key];
      if(!match)return null;
      const details=await readPromptFile(fetcher,'answer/'+bucketFor(match)+'.bin');
      return details[match];
    });
    if(words.length>=2&&!hasSavedProblem){
      const key=normalizeQuestion(input);
      const match=await lookup(key).catch(()=>null);
      if(match){
        const archived={row:{...match,id:match.id,title:match.topic,answer:match.answer},links:linksFor(match)};
        remember(archived);
        return report(match.id,intent,match.answer,{title:match.topic,links:archived.links,
          actions:[['Break it down','Can you break it down?']]});
      }
    }
    reset();
    return null;
  }
  return {respond,reset};
}

