export const learnerVisuals = Object.freeze(definitions.map(definition => Object.freeze({
  ...definition,
  aliases: Object.freeze(definition.aliases),
  source: Object.freeze(definition.source),
  frames: Object.freeze(definition.frames.map(Object.freeze))
})));

export function findLearnerVisual({topic = '', prompt = ''} = {}) {
  const query = String(prompt);
  if (/\b(?:handout|worksheet|pdf|download|resource links?|where can i find)\b/i.test(query)) return null;
  const eligible = visual => !visual.exclude.test(query);
  const assigned = learnerVisuals.find(visual => visual.aliases.includes(topic));
  if (assigned) return eligible(assigned) ? assigned : null;
  if (topic && !topicsWithContext.has(topic)) return null;
  return learnerVisuals.find(visual => eligible(visual) && visual.cue.test(query)) ?? null;
}

function svgPart(parent, tag, attributes, content) {
  const element = parent.ownerDocument.createElementNS(SVG_NAMESPACE, tag);
  for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, value);
  if (content) element.textContent = content;
  parent.append(element);
  return element;
}

function path(parent, d, stroke, fill = 'none', width = 2, extra = {}) {
  return svgPart(parent, 'path', {d, stroke, fill, 'stroke-width': width, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', ...extra});
}

function text(parent, x, y, label, extra = {}) {
  return svgPart(parent, 'text', {x, y, fill: palette.ink, 'text-anchor': 'middle', 'font-size': 14, 'font-family': 'system-ui,sans-serif', ...extra}, label);
}

function circle(parent, cx, cy, r, fill, stroke = 'none') {
  return svgPart(parent, 'circle', {cx, cy, r, fill, stroke, 'stroke-width': 2});
}

function ellipse(parent, cx, cy, rx, ry, fill, stroke) {
  return svgPart(parent, 'ellipse', {cx, cy, rx, ry, fill, stroke, 'stroke-width': 2});
}

function horizontalArrow(parent, x1, x2, y, color, width) {
  const tail = x2 - Math.sign(x2 - x1) * 8;
  path(parent, 'M ' + x1 + ' ' + y + ' H ' + x2 + ' M ' + tail + ' ' + (y - 6) + ' L ' + x2 + ' ' + y + ' L ' + tail + ' ' + (y + 6), color, 'none', width);
}

const chromatin = [
  'M-22 -14 q12 -13 17 3 t-4 12', 'M8 -23 q11 -11 16 3 t-14 9',
  'M-23 17 q8 -15 20 -8 t-1 14', 'M10 12 q12 -14 16 0 t-11 8'
];

function drawChromatin(svg, x, y, scale = 1) {
  const group = svgPart(svg, 'g', {transform: 'translate(' + x + ' ' + y + ') scale(' + scale + ')'});
  chromatin.forEach((curve, index) => path(group, curve, index % 2 === 0 ? palette.purple : palette.rose));
}

function chromosome(svg, x, y, index, replicated, direction = 1) {
  const size = index < 2 ? 8 : 6;
  const stroke = index % 2 === 0 ? palette.purple : palette.rose;
  const group = svgPart(svg, 'g', {transform: 'translate(' + x + ' ' + y + ') scale(' + direction + ' 1)'});
  const segment = 'M' + -size + ' ' + -size + ' L0 0 L' + -size + ' ' + size;
  path(group, segment, stroke, 'none', 4);
  if (replicated) path(group, 'M' + size + ' ' + -size + ' L0 0 L' + size + ' ' + size, stroke, 'none', 4);
  circle(group, 0, 0, 2.3, palette.ink);
}

