  if (frame === 4) {
    path(svg, 'M 32 105 C 32 28 155 22 200 66 C 245 22 368 28 368 105 C 368 182 245 188 200 144 C 155 188 32 182 32 105 Z', palette.rose, palette.shell);
    for (const x of [117, 283]) {
      ellipse(svg, x, 105, 36, 35, palette.nucleus, palette.purple);
