  if (frame === 1) {
    path(svg, 'M158 63 A55 48 0 0 1 214 57 M243 71 A55 48 0 0 1 250 123 M221 148 A55 48 0 0 1 163 142 M149 116 A55 48 0 0 1 147 89', palette.purple, 'none', 2, {'stroke-dasharray': '5 6'});
  }
  for (const x of [72, 328]) {
    const left = x < 200;
    points.forEach(([px, y], index) => {
      const endX = frame === 3 ? (left ? 122 : 278) : px;
